from __future__ import annotations

from dataclasses import dataclass
from threading import RLock
from typing import Dict


class LoginGuard:
    """
    In-memory rate limiter for online guessing protection.

    Implements: "limit consecutive failed authentication attempts on a single account
    to no more than 100" (NIST SP 800-63B §5.2.2 excerpt).

    Semantics:
      - failed(account): increments consecutive failures; once count reaches 100,
        account becomes locked.
      - succeeded(account): resets consecutive failure count (unlocking if locked).
      - locked(account): returns True if consecutive failures >= 100, else False.
    """

    _MAX_CONSECUTIVE_FAILED = 100

    @dataclass
    class _State:
        consecutive_failed: int = 0

    def __init__(self) -> None:
        self._lock = RLock()
        self._states: Dict[str, LoginGuard._State] = {}

    def failed(self, account: str) -> None:
        if not isinstance(account, str) or account == "":
            raise ValueError("account must be a non-empty string")

        with self._lock:
            state = self._states.get(account)
            if state is None:
                state = self._State(consecutive_failed=0)
                self._states[account] = state

            # Saturate at the lock threshold to avoid unbounded growth.
            if state.consecutive_failed < self._MAX_CONSECUTIVE_FAILED:
                state.consecutive_failed += 1
            else:
                state.consecutive_failed = self._MAX_CONSECUTIVE_FAILED

    def succeeded(self, account: str) -> None:
        if not isinstance(account, str) or account == "":
            raise ValueError("account must be a non-empty string")

        with self._lock:
            # Reset consecutive failures on successful authentication.
            state = self._states.get(account)
            if state is None:
                # Nothing to reset; keep storage tidy.
                return
            state.consecutive_failed = 0

    def locked(self, account: str) -> bool:
        if not isinstance(account, str) or account == "":
            raise ValueError("account must be a non-empty string")

        with self._lock:
            state = self._states.get(account)
            if state is None:
                return False
            return state.consecutive_failed >= self._MAX_CONSECUTIVE_FAILED
